\begin{enumerate}
  \item $a_1<a_2<\dots<a_n$ とする．$f(x)=\displaystyle\sum_{i=1}^n(x-a_i)^2$ を最小にする $x$ を求めよ．
  \item $g(x)=\displaystyle\sum_{k=1}^{10}k|x-k|$ を最小にする $x$ と，その最小値を求めよ．
\end{enumerate}

2つの変量 $x,y$ が，$i=1,2,\dots,n$ に対して $x_i=2i-1$，$y_i=2(n+1-i)$ で与えられている（$n\geqq2$）．
\begin{enumerate}
  \item 変量 $x$ の平均値 $m_x$ と分散 $s_x^2$ を求めよ．
  \item 変量 $x$ と変量 $y$ の相関係数 $r$ を求めよ．
  \item $n$ 個の変量 $x$ に，平均値 $3n$，分散 $2n^2$ からなる $n$ 個のデータを加えた．この $2n$ 個のデータの平均値 $m'$ と分散 $s'^2$ を求めよ．
\end{enumerate}

$n$ 個のデータ $(x_1,y_1),\dots,(x_n,y_n)$ について，$x$ の平均 $\bar x$，分散 $s_x^2$（$>0$），$y$ の平均 $\bar y$，分散 $s_y^2$，共分散 $s_{xy}$ とする．
\begin{enumerate}
  \item $Q(a,b)=\displaystyle\sum_{i=1}^n(y_i-ax_i-b)^2$ を最小にする $a,b$ は $a=\dfrac{s_{xy}}{s_x^2}$，$b=\bar y-a\bar x$ であることを示せ．
  \item $Q$ の最小値は $ns_y^2(1-r^2)$（$r$ は相関係数）であることを示し，$|r|\leqq1$ を導け．
  \item データ $(1,2),(2,3),(3,5),(4,6)$ の回帰直線 $y=ax+b$ を求めよ．
\end{enumerate}

あるクラスの10人が受けた国語と数学の小テストの得点（整数）を度数分布表にまとめた．
\begin{center}
\begin{tabular}{c|cc}
階級（点） & 国語 & 数学\\\hline
40以上49以下 & 3 & 1\\
50〜59 & 3 & 2\\
60〜69 & 2 & 4\\
70〜79 & 2 & 3\\\hline
計 & 10 & 10
\end{tabular}
\end{center}
\begin{enumerate}
  \item 国語の得点の中央値として考えられる最小の値と最大の値を求めよ．
  \item 国語の平均値 $M_1$，数学の平均値 $M_2$ のとりうる値の範囲をそれぞれ求めよ．
  \item $M_2-M_1$ のとりうる値の範囲を求めよ．また，次のうち正しいものをすべて選べ．\\
  ① $M_1=M_2$ となる場合がある \quad ② $M_1>M_2$ となる場合がある \quad ③ $M_1<M_2-15$ となる場合がある
\end{enumerate}

ある学校の4種類のテスト A，B，C，D（各100点満点，得点は整数）について，50人の得点の5数要約が次のようであった．
\begin{center}
\begin{tabular}{c|ccccc}
 & 最小値 & 第1四分位数 & 中央値 & 第3四分位数 & 最大値\\\hline
A & 25 & 40 & 57 & 73 & 90\\
B & 20 & 33 & 45 & 58 & 78\\
C & 28 & 61 & 70 & 82 & 95\\
D & 45 & 64 & 72 & 80 & 96
\end{tabular}
\end{center}
ただし，第1四分位数は小さい方から13番目，第3四分位数は38番目の値とする．
\begin{enumerate}
  \item 38人以上が60点以上であると確実にいえるテストはどれか．
  \item 40点未満の生徒が13人以上いると確実にいえるテストはどれか．
  \item テストCで40点以上の生徒は最も多くて何人と考えられるか．
  \item テストBで40点以上60点未満の生徒は少なくとも何人いるか．
\end{enumerate}

ある団体50人の体重を測定し，次の度数分布表を得た．
\begin{center}
\begin{tabular}{c|cccccc|c}
体重（kg） & 40〜44 & 44〜48 & 48〜52 & 52〜56 & 56〜60 & 60〜64 & 計\\\hline
度数 $f$ & 4 & 8 & 15 & 12 & 7 & 4 & 50
\end{tabular}
\end{center}
（各階級は「以上〜未満」）階級値を $x$ とし，$u=\dfrac{x-50}4$ とする．
\begin{enumerate}
  \item $\sum uf$，$\sum u^2f$ を求め，$u$ の平均値 $\bar u$ と分散 $s_u^2$ を求めよ．
  \item $x$ の平均値 $\bar x$ と分散 $s_x^2$ を求めよ．
  \item 中央値が含まれる階級の階級値を答えよ．
\end{enumerate}

$a,b,c$ は異なる3つの正の整数とする．10人が受けた科目X，Yの得点は次のとおりである．
\begin{center}
\begin{tabular}{c|cccccccccc}
 & ① & ② & ③ & ④ & ⑤ & ⑥ & ⑦ & ⑧ & ⑨ & ⑩\\\hline
X & $a$ & $b$ & $c$ & $c$ & $b$ & $a$ & $c$ & $b$ & $c$ & $a$\\
Y & $b$ & $a$ & $b$ & $b$ & $a$ & $c$ & $a$ & $b$ & $a$ & $b$
\end{tabular}
\end{center}
X の平均値と Y の平均値は等しいとする．
\begin{enumerate}
  \item $a,b,c$ の間に成り立つ関係式を求めよ．
  \item X の分散を $s_X^2$，Y の分散を $s_Y^2$ とするとき，$\dfrac{s_X^2}{s_Y^2}$ を求めよ．
  \item X と Y の相関係数を，四捨五入して小数第1位まで求めよ．
  \item X の中央値が65，Y の分散が201であるとき，$a,b,c$ の組をすべて求めよ．
\end{enumerate}

30人の2つの変量 $x,y$ について，平均値 $\bar x=20$，$\bar y=30$，分散 $s_x^2=16$，$s_y^2=25$，共分散 $s_{xy}=12$ であった．
\begin{enumerate}
  \item $x$ と $y$ の相関係数を求めよ．
  \item 31人目として $(x,y)=(20,30)$ のデータを加えた．新しい共分散 $A$ ともとの共分散 $B$，新しい相関係数 $C$ ともとの相関係数 $D$ の大小関係を答えよ．
  \item (2) の代わりに $(x,y)=(24,25)$ のデータを加えたとき，新しい相関係数を求めよ．
\end{enumerate}

次のデータは，ある10日間の最高気温（℃）を小さい順に並べたものである．
$12,\ 15,\ 18,\ 20,\ 21,\ 24,\ 26,\ 27,\ 30,\ 33$
\begin{enumerate}
